DO $$
BEGIN
    IF to_regclass('lifecycle.clearance_items') IS NOT NULL AND to_regclass('lifecycle.offboardings') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('lifecycle.clearance_items') AND c.contype = 'f' AND a.attname = 'offboarding_id'
    ) THEN
        ALTER TABLE lifecycle.clearance_items ADD CONSTRAINT fk_clearance_items_offboarding_id FOREIGN KEY (offboarding_id) REFERENCES lifecycle.offboardings (id) NOT VALID;
        BEGIN
            ALTER TABLE lifecycle.clearance_items VALIDATE CONSTRAINT fk_clearance_items_offboarding_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_clearance_items_offboarding_id left NOT VALID: stored rows of lifecycle.clearance_items reference missing rows';
        END;
    END IF;
END $$;

